class FencedStorage {
    private long highestToken = 0;
    String value = "";

    synchronized boolean write(long token, String newValue) {
        if (token < highestToken) return false;
        highestToken = token;
        value = newValue;
        return true;
    }
}

var storage = new FencedStorage();
System.out.println(storage.write(33, "A1") + " " + storage.write(34, "B1") + " "
        + storage.write(33, "A2") + " " + storage.write(34, "B2") + " value=" + storage.value);
